Evaluate the JavaScript sorting algorithms visualizer implementation on a scale of 0-10 points:

**Algorithm Implementation (4 points)**: Does it correctly implement all five sorting algorithms (Bubble, Quick, Merge, Heap, Radix) with accurate logic and complexity analysis?

**Visualization Quality (3 points)**: Does it provide clear visual feedback with proper color coding, call stack visualization for recursive algorithms, and working area highlighting?

**Interactive Features (2 points)**: Does it include functional controls (algorithm selection, speed control, step/continuous modes, scramble patterns) and real-time statistics?

**Performance & Code Quality (1 point)**: Does it run smoothly at 60 FPS with well-structured, educational code?

Solution A: function initSortVisualizer(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    canvas.width = 500;
    canvas.height = 500;
    const ctx = canvas.getContext('2d');

    const N = 50;
    let arrData = [];
    let comparisons = 0;
    let swaps = 0;
    let recDepth = 0;
    let algorithm = 'Bubble';
    let speed = 5; // 1 (slow) to 10 (fast)
    let stepMode = false;
    let continuousTimer = null;
    let generator = null;

    // UI Elements
    const container = document.createElement('div');
    container.style.display = 'flex';
    container.style.flexDirection = 'column';
    container.style.alignItems = 'center';
    container.style.fontFamily = 'sans-serif';
    container.style.margin = '10px';

    const controls = document.createElement('div');
    controls.style.display = 'flex';
    controls.style.gap = '10px';
    controls.style.marginBottom = '10px';

    const algSelect = document.createElement('select');
    ['Bubble', 'Quick', 'Merge', 'Heap', 'Radix'].forEach(name => {
        const opt = document.createElement('option');
        opt.value = name;
        opt.text = name;
        algSelect.appendChild(opt);
    });
    controls.appendChild(algSelect);

    const speedLabel = document.createElement('label');
    speedLabel.textContent = 'Speed:';
    const speedSlider = document.createElement('input');
    speedSlider.type = 'range';
    speedSlider.min = '1';
    speedSlider.max = '10';
    speedSlider.value = speed.toString();
    speedLabel.appendChild(speedSlider);
    controls.appendChild(speedLabel);

    const stepToggle = document.createElement('label');
    stepToggle.textContent = 'Step-by-step';
    const stepCheckbox = document.createElement('input');
    stepCheckbox.type = 'checkbox';
    stepToggle.appendChild(stepCheckbox);
    controls.appendChild(stepToggle);

    const scramblePatternSelect = document.createElement('select');
    ['Random', 'Reverse', 'Nearly Sorted'].forEach(name => {
        const opt = document.createElement('option');
        opt.value = name;
        opt.text = name;
        scramblePatternSelect.appendChild(opt);
    });
    controls.appendChild(scramblePatternSelect);

    const scrambleButton = document.createElement('button');
    scrambleButton.textContent = 'Scramble';
    controls.appendChild(scrambleButton);

    const nextButton = document.createElement('button');
    nextButton.textContent = 'Next';
    nextButton.style.display = 'none';
    controls.appendChild(nextButton);

    const counterDiv = document.createElement('div');
    counterDiv.textContent = 'Comparisons: 0 Swaps: 0 Recursion Depth: 0 Complexity: O(n^2)';
    counterDiv.style.marginTop = '10px';

    container.appendChild(controls);
    container.appendChild(counterDiv);
    document.body.appendChild(container);

    function resetCounters() {
        comparisons = 0;
        swaps = 0;
        recDepth = 0;
    }

    function render() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const barWidth = canvas.width / N;
        const maxVal = Math.max(...arrData.map(d => d.value));
        arrData.forEach((d, i) => {
            const valRatio = d.value / maxVal;
            const barHeight = valRatio * canvas.height * 0.9;
            ctx.fillStyle = getColor(d.status);
            ctx.fillRect(i * barWidth, canvas.height - barHeight, barWidth - 2, barHeight);
        });
    }

    function getColor(status) {
        switch (status) {
            case 'compare': return 'red';
            case 'swap': return 'yellow';
            case 'sorted': return 'green';
            case 'pivot': return 'blue';
            case 'working': return '#d3d3d3';
            default: return 'white';
        }
    }

    function shuffle(array) {
        for (let i = array.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [array[i], array[j]] = [array[j], array[i]];
        }
    }

    function scramble(pattern) {
        if (pattern === 'Random') {
            arrData = arrData.map((_, i) => ({ value: i + 1, status: 'default' }));
            shuffle(arrData);
        } else if (pattern === 'Reverse') {
            arrData = arrData.map((_, i) => ({ value: N - i, status: 'default' }));
        } else if (pattern === 'Nearly Sorted') {
            arrData = arrData.map((_, i) => ({ value: i + 1, status: 'default' }));
            for (let i = 0; i < Math.floor(N / 10); i++) {
                const a = Math.floor(Math.random() * N);
                const b = Math.floor(Math.random() * N);
                [arrData[a], arrData[b]] = [arrData[b], arrData[a]];
            }
        }
        render();
    }

    function getComplexity(name) {
        const map = {
            Bubble: 'O(n²)',
            Quick: 'O(n log n) average, O(n²) worst',
            Merge: 'O(n log n)',
            Heap: 'O(n log n)',
            Radix: 'O(k n)'
        };
        return map[name] || '';
    }

    function advance() {
        if (!generator) return;
        const { done } = generator.next();
        render();
        counterDiv.textContent = `Comparisons: ${comparisons} Swaps: ${swaps} Recursion Depth: ${recDepth} Complexity: ${getComplexity(algorithm)}`;
        if (done) {
            arrData.forEach(d => d.status = 'sorted');
            render();
            if (continuousTimer) clearInterval(continuousTimer);
            continuousTimer = null;
        } else if (!stepMode && continuousTimer === null) {
            startContinuous();
        }
    }

    function startContinuous() {
        if (continuousTimer) clearInterval(continuousTimer);
        const delay = 1000 / (speed * 2);
        continuousTimer = setInterval(() => {
            advance();
        }, delay);
    }

    function stopContinuous() {
        if (continuousTimer) {
            clearInterval(continuousTimer);
            continuousTimer = null;
        }
    }

    // Sorting Algorithm Generators
    function* bubbleSort(data) {
        const n = data.length;
        for (let i = 0; i < n - 1; i++) {
            for (let j = 0; j < n - i - 1; j++) {
                data[j].status = 'compare';
                data[j + 1].status = 'compare';
                yield;
                comparisons++;
                if (data[j].value > data[j + 1].value) {
                    data[j].status = 'swap';
                    data[j + 1].status = 'swap';
                    yield;
                    swaps++;
                    [data[j].value, data[j + 1].value] = [data[j + 1].value, data[j].value];
                    yield;
                }
                data[j].status = 'default';
                data[j + 1].status = 'default';
            }
        }
    }

    function* quickSort(data, left, right) {
        if (left < right) {
            const pivotIdx = left + Math.floor((right - left) / 2);
            const pivotVal = data[pivotIdx].value;
            data[pivotIdx].status = 'pivot';
            yield;
            recDepth++;
            let i = left, j = right;
            while (i <= j) {
                while (data[i].value < pivotVal) {
                    data[i].status = 'compare';
                    yield;
                    comparisons++;
                    data[i].status = 'default';
                    i++;
                }
                while (data[j].value > pivotVal) {
                    data[j].status = 'compare';
                    yield;
                    comparisons++;
                    data[j].status = 'default';
                    j--;
                }
                if (i <= j) {
                    data[i].status = 'swap';
                    data[j].status = 'swap';
                    yield;
                    swaps++;
                    [data[i].value, data[j].value] = [data[j].value, data[i].value];
                    yield;
                    data[i].status = 'default';
                    data[j].status = 'default';
                    i++;
                    j--;
                }
            }
            data[pivotIdx].status = 'default';
            yield;
            recDepth--;
            yield* quickSort(data, left, j);
            yield* quickSort(data, i, right);
        }
    }

    function* mergeSort(data, left, right) {
        if (left < right) {
            const mid = Math.floor((left + right) / 2);
            yield* mergeSort(data, left, mid);
            yield* mergeSort(data, mid + 1, right);
            const leftArr = data.slice(left, mid + 1).map(d => ({ value: d.value }));
            const rightArr = data.slice(mid + 1, right + 1).map(d => ({ value: d.value }));
            let i = 0, j = 0, k = left;
            while (i < leftArr.length && j < rightArr.length) {
                leftArr[i].status = 'compare';
                rightArr[j].status = 'compare';
                yield;
                comparisons++;
                if (leftArr[i].value <= rightArr[j].value) {
                    data[k].value = leftArr[i].value;
                    data[k].status = 'swap';
                    yield;
                    swaps++;
                    data[k].status = 'default';
                    i++;
                } else {
                    data[k].value = rightArr[j].value;
                    data[k].status = 'swap';
                    yield;
                    swaps++;
                    data[k].status = 'default';
                    j++;
                }
                k++;
            }
            while (i < leftArr.length) {
                data[k].value = leftArr[i].value;
                data[k].status = 'swap';
                yield;
                swaps++;
                data[k].status = 'default';
                i++; k++;
            }
            while (j < rightArr.length) {
                data[k].value = rightArr[j].value;
                data[k].status = 'swap';
                yield;
                swaps++;
                data[k].status = 'default';
                j++; k++;
            }
        }
    }

    function* heapSort(data) {
        const n = data.length;
        const heapify = function (size, root) {
            let largest = root;
            const l = 2 * root + 1;
            const r = 2 * root + 2;
            if (l < size && data[l].value > data[largest].value) largest = l;
            if (r < size && data[r].value > data[largest].value) largest = r;
            if (largest !== root) {
                data[root].status = 'swap';
                data[largest].status = 'swap';
                yield;
                swaps++;
                [data[root].value, data[largest].value] = [data[largest].value, data[root].value];
                yield;
                data[root].status = 'default';
                data[largest].status = 'default';
                yield* heapify(size, largest);
            }
        };
        for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
            yield* heapify(n, i);
        }
        for (let i = n - 1; i > 0; i--) {
            data[0].status = 'swap';
            data[i].status = 'swap';
            yield;
            swaps++;
            [data[0].value, data[i].value] = [data[i].value, data[0].value];
            yield;
            data[0].status = 'default';
            data[i].status = 'default';
            yield* heapify(i, 0);
        }
    }

    function* radixSort(data) {
        const base = 10;
        const max = Math.max(...data.map(d => d.value));
        let exp = 1;
        while (Math.floor(max / exp) > 0) {
            const bucket = Array.from({ length: base }, () => []);
            for (let i = 0; i < data.length; i++) {
                data[i].status = 'compare';
                yield;
                comparisons++;
                const idx = Math.floor((data[i].value / exp) % base);
                bucket[idx].push({ value: data[i].value });
                data[i].status = 'default';
            }
            let index = 0;
            for (let i = 0; i < base; i++) {
                for (let j = 0; j < bucket[i].length; j++) {
                    data[index].value = bucket[i][j].value;
                    data[index].status = 'swap';
                    yield;
                    swaps++;
                    data[index].status = 'default';
                    index++;
                }
            }
            exp *= base;
        }
    }

    function getGenerator() {
        const data = arrData;
        if (algorithm === 'Bubble') return bubbleSort(data);
        if (algorithm === 'Quick') return quickSort(data, 0, data.length - 1);
        if (algorithm === 'Merge') return mergeSort(data, 0, data.length - 1);
        if (algorithm === 'Heap') return heapSort(data);
        if (algorithm === 'Radix') return radixSort(data);
    }

    function startSorting() {
        stopContinuous();
        resetCounters();
        generator = getGenerator();
        advancedId = null;
        advance();
    }

    // Event listeners
    scrambleButton.addEventListener('click', () => {
        scramble(scramblePatternSelect.value);
        startSorting();
    });

    algSelect.addEventListener('change', () => {
        algorithm = algSelect.value;
        counterDiv.textContent = `Comparisons: ${comparisons} Swaps: ${swaps} Recursion Depth: ${recDepth} Complexity: ${getComplexity(algorithm)}`;
    });

    speedSlider.addEventListener('input', (e) => {
        speed = parseInt(e.target.value, 10);
    });

    stepCheckbox.addEventListener('change', (e) => {
        stepMode = e.target.checked;
        nextButton.style.display = stepMode ? '' : 'none';
        if (stepMode) stopContinuous();
    });

    nextButton.addEventListener('click', () => {
        advance();
    });

    // Initial scramble and start
    scramble('Random');
    startSorting();
}

